import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

// NOTE: Use the base URL of your Spring Boot Backend
const API_BASE_URL = "http://localhost:9091"; 

function CartPage() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  // Get cart items from localStorage
  const cartItems = JSON.parse(localStorage.getItem("cart")) || [];

  // Calculate the total amount
  const total = cartItems.reduce(
    (sum, item) => sum + item.price * item.quantity,
    0
  );

  // --- INTERACTIVE ENHANCEMENT: API CALL TO PLACE ORDER ---
  const handlePlaceOrder = async () => {
    setMessage(""); // Clear previous messages
    if (cartItems.length === 0) {
      setMessage("Your cart is empty. Add items before checking out.");
      return;
    }

    // 1. Get current user data (assuming it's stored in localStorage upon login)
    const userData = JSON.parse(localStorage.getItem("user"));
    if (!userData || !userData.username) {
      setMessage("❌ Error: Please log in to complete your order.");
      return;
    }
    
    setLoading(true);

    const orderPayload = {
      username: userData.username,
      totalAmount: total,
      // Send the cart contents as a JSON string for the backend to store
      orderDetailsJson: JSON.stringify(cartItems), 
    };

    try {
      const response = await axios.post(
        `${API_BASE_URL}/api/orders/place`, 
        orderPayload
      );
      
      setMessage(`✅ Order Placed Successfully! Order ID: ${response.data.orderId || 'N/A'}`);
      
      // 2. Clear the cart after a successful order
      localStorage.setItem("cart", JSON.stringify([]));
      
      // 3. Redirect to a confirmation/history page for a better flow
      setTimeout(() => {
        navigate("/order-history"); // Assuming you create an OrderHistory route
      }, 2000);

    } catch (error) {
      console.error("Order failed:", error);
      setMessage("❌ Failed to place order. Server or network issue.");
    } finally {
      setLoading(false);
    }
  };

  // --- REMOVED: handleCheckout is replaced by handlePlaceOrder ---
  // The old handleCheckout only navigated; the new one completes the transaction.


  // --- REMOVE ITEM FUNCTION (Highly Interactive Feature) ---
  const handleRemoveItem = (id) => {
    const updatedCart = cartItems.filter(item => item.id !== id);
    localStorage.setItem("cart", JSON.stringify(updatedCart));
    // Force component re-render (since state isn't used for cart, this ensures UI updates)
    window.dispatchEvent(new Event('storage')); // Simple way to force re-render if CartPage uses a global listener or state refresh.
    // NOTE: For a React best practice, the cart should be managed by a global state (Context or Redux) to avoid this manual trick.
    // For now, refreshing the page or navigating back and forth would also show the change.
    setMessage(`Item removed from cart.`);
  };

  return (
    <div className="p-6 max-w-3xl mx-auto">
      <h2 className="text-3xl font-extrabold text-indigo-800 mb-6 border-b pb-2">
        🛒 Your Shopping Cart
      </h2>
      
      {/* Display messages/alerts */}
      {message && (
        <div className={`p-3 mb-4 rounded ${message.startsWith('❌') ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'}`}>
          {message}
        </div>
      )}

      {cartItems.length === 0 ? (
        <p className="text-xl text-gray-500 text-center py-10">
          🛍️ Your cart is empty. Time to find some wellness!
        </p>
      ) : (
        <>
          <div className="space-y-4 mb-8">
            {cartItems.map((item, index) => (
              <div
                key={index}
                className="flex justify-between items-center bg-white p-4 rounded-xl shadow-md transition duration-300 hover:shadow-lg"
              >
                <div className="flex-grow">
                  <h3 className="font-semibold text-lg text-gray-800">{item.name}</h3>
                  <p className="text-sm text-gray-500">
                    Price: ₹{item.price.toFixed(2)} | Quantity: <span className="font-medium text-indigo-600">{item.quantity}</span>
                  </p>
                </div>
                
                <div className="text-right">
                    <span className="font-extrabold text-xl text-indigo-700 block">
                      ₹{(item.price * item.quantity).toFixed(2)}
                    </span>
                    <button 
                        onClick={() => handleRemoveItem(item.id)}
                        className="text-red-500 hover:text-red-700 text-sm mt-1 focus:outline-none"
                    >
                        Remove
                    </button>
                </div>
              </div>
            ))}
          </div>

          <div className="flex justify-between font-extrabold text-2xl border-t pt-4 mt-6">
            <span>Order Total:</span>
            <span className="text-green-600">₹{total.toFixed(2)}</span>
          </div>

          <button
            onClick={handlePlaceOrder}
            disabled={loading}
            className={`w-full py-3 mt-6 text-white rounded-lg font-bold transition duration-300 ${
              loading
                ? "bg-gray-400 cursor-not-allowed"
                : "bg-indigo-600 hover:bg-indigo-700 shadow-lg"
            }`}
          >
            {loading ? "Processing Order..." : "🚀 Complete and Place Order"}
          </button>
        </>
      )}
    </div>
  );
}

export default CartPage;
